h2. Implementation ideas (optional)
{code:java}
protected void removeEventWithRowId(LogMinerEventRow row) {
    MemoryTransaction transaction = getTransactionCache().get(row.getTransactionId());
    if (transaction == null) {
        String txid = row.getTransactionId();
        if (txid.toLowerCase().indexOf("ffffff") > 0) {
            String frontWords = txid.substring(0, txid.toLowerCase().indexOf("ffffff"));
            Optional<String> newTxid = Optional.empty();
            Iterator<Map.Entry<String, MemoryTransaction>> iterator = transactionCache.iterator();
            while (iterator.hasNext()) {
                Map.Entry<String, MemoryTransaction> entry = iterator.next();
                if (entry.getKey().startsWith(frontWords)) {
                    newTxid = Optional.of(entry.getKey());
                    break;
                }
            }
            if (newTxid.isPresent()) {
                transaction = getTransactionCache().get(newTxid.get());
            }
        }
        if (transaction == null) {
            LOGGER.warn("Cannot undo change '{}' since transaction was not found.", row);
            return;
        }
    }
    transaction.removeEventWithRowId(row.getRowId());
}{code}

